#include "cpu/chroma_median.hpp"
#include <algorithm>
#include <cstdint>

// Input/output RGB. Eight separately defined final refinements share the two
// immutable 3x3 chroma medians; this experimental scorer is not a timed kernel.
extern "C" void post(const uint8_t* source, uint8_t* outputs, int width, int height, int rggb) {
    const size_t plane = static_cast<size_t>(width) * height * 3;
    for (int y = 0; y < height; ++y) for (int x = 0; x < width; ++x) {
        int differences[2][9];
        for (int j = -1; j <= 1; ++j) for (int i = -1; i <= 1; ++i) {
            const int xx = x+i < 0 ? 1 : x+i >= width ? width-2 : x+i;
            const int yy = y+j < 0 ? 1 : y+j >= height ? height-2 : y+j;
            const uint8_t* q = source + (static_cast<size_t>(yy)*width+xx)*3;
            differences[0][(j+1)*3+i+1] = int(q[0])-q[1];
            differences[1][(j+1)*3+i+1] = int(q[2])-q[1];
        }
        int med[2];
        for (int c=0;c<2;++c) {
            const int* d=differences[c];
            med[c]=median_cpu_detail::median9(d[0],d[1],d[2],d[3],d[4],d[5],d[6],d[7],d[8]);
        }
        const size_t offset=(static_cast<size_t>(y)*width+x)*3;
        const uint8_t* s=source+offset;
        const bool chromatic=((x^y)&1)==0;
        const int measured = chromatic ? ((((x&1)==0)==bool(rggb)) ? 0 : 2) : 1;
        const int delta=chromatic ? int(s[measured])-med[measured/2]-s[1] : 0;
        for (int mode=0;mode<8;++mode) {
            int change=0;
            if (mode==1 || mode==4) change=delta;
            if (mode==2 || mode==5) change=(delta+1)>>1;
            if (mode==3) change=(delta+2)>>2;
            if (mode==6) change=std::clamp(delta,-8,8);
            if (mode==7) change=std::abs(delta)<=16 ? delta : 0;
            const int green=std::clamp(int(s[1])+change,0,255);
            const int chroma_green=(mode==4 || mode==5) ? s[1] : green;
            uint8_t* out=outputs+plane*mode+offset;
            out[1]=green;
            for (int c : {0,2}) out[c]=measured==c ? s[c] : std::clamp(chroma_green+med[c/2],0,255);
        }
    }
}
